import{_ as o,a0 as n,w as i,s as d,ao as a,I as t,x as s,a1 as l,A as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const h=JSON.parse('{"title":"開源 DevOps 工具的平台化未來 | LCTT x X-CMD","titleTemplate":false,"description":"開源 DevOps 工具的平台化未來 | LCTT (202210) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"開源 DevOps 工具的平台化未來 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"開源 DevOps 工具的平台化未來 | LCTT (202210) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202210/20221017.3 ⭐️⭐️⭐️ Open source DevOps tools in a platform future","title":"開源 DevOps 工具的平台化未來","tag":"202210","desc":""},"relativePath":"202210/20221017.3 ⭐️⭐️⭐️ Open source DevOps tools in a platform future.md","filePath":"[post].md"}'),u={name:"202210/20221017.3 ⭐️⭐️⭐️ Open source DevOps tools in a platform future.md"};function v(D,e,O,b,f,m){const p=n("Link");return i(),d("div",null,[e[30]||(e[30]=a('<h1 id="開源-devops-工具的平台化未來" tabindex="-1">開源 DevOps 工具的平台化未來 <a class="header-anchor" href="#開源-devops-工具的平台化未來" aria-label="Permalink to “開源 DevOps 工具的平台化未來”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202210/24/092748lwwoicus5e4s59gg.jpg" alt=""></p><blockquote><p>當商業 DevOps 工具市場着眼於平台時，是時候讓開源 DevOps 工具重新定義它們的未來了。</p></blockquote><p>DevOps 的開源根基是無法動搖的，即便有預言稱全球的 DevOps 市場將在 2026 年之前達到 178 億美元。不斷變化的工作環境、安全和合規性問題，以及風險投資公司等等因素正在將市場推向 DevOps 平台，開發團隊可以在雲中獲得完整的端到端 DevOps 工具鏈。</p><h3 id="開源-devops-工具現狀" tabindex="-1">開源 DevOps 工具現狀 <a class="header-anchor" href="#開源-devops-工具現狀" aria-label="Permalink to “開源 DevOps 工具現狀”">​</a></h3><p>我們要搞清楚一件事：開源工具不可能從 DevOps 世界中消失。現在，在開源和供應商提供的 DevOps 工具之間存在着一種平衡，開發人員會在兩者間選擇適合他們的工具。事實上，很多情況下，一個開發團隊起初會為他們的 DevOps 流水線選擇一個開源工具，後來又升級到商業版本。</p><h3 id="三種開源-devops-工具實例" tabindex="-1">三種開源 DevOps 工具實例 <a class="header-anchor" href="#三種開源-devops-工具實例" aria-label="Permalink to “三種開源 DevOps 工具實例”">​</a></h3><p>下面我們介紹一些開源 DevOps 工具的例子，每種工具都已經有了圍繞其建立的商業化生態。</p><h4 id="git" tabindex="-1">Git <a class="header-anchor" href="#git" aria-label="Permalink to “Git”">​</a></h4>',9)),t("p",null,[e[1]||(e[1]=s("源代碼管理工具 ",-1)),l(p,{href:"https://opensource.com/article/22/4/our-favorite-git-commands"},{default:r(()=>[...e[0]||(e[0]=[s("Git",-1)])]),_:1}),e[2]||(e[2]=s(" 作為源代碼庫，可能是 DevOps 工具鏈的主要基礎之一。",-1))]),t("p",null,[e[4]||(e[4]=s("Git 的兩個最佳商業案例是 GitLab 和 GitHub。GitLab ",-1)),l(p,{href:"https://opensource.com/article/19/9/how-contribute-gitlab"},{default:r(()=>[...e[3]||(e[3]=[s("接受開發者對其貢獻開源項目",-1)])]),_:1}),e[5]||(e[5]=s("。GitHub 也在着手努力成為一個 DevOps 平台，推出了人工智能版的結對編程 GitHub Copilot，在推出後受到了一些開源團體的褒貶不一的評價。",-1))]),e[31]||(e[31]=t("h4",{id:"jenkins",tabindex:"-1"},[s("Jenkins "),t("a",{class:"header-anchor",href:"#jenkins","aria-label":"Permalink to “Jenkins”"},"​")],-1)),e[32]||(e[32]=t("p",null,"作為一個開源的自動化服務，Jenkins 因其易於安裝、配置和可擴展性而受到推崇。",-1)),e[33]||(e[33]=t("p",null,"CloudBees 提供了 JenkinsX，JenkinsX 是一套開源的解決方案，可以為 Kubernetes 上的雲原生應用提供自動化持續集成和持續交付（CI/CD）以及自動化測試工具。他們還為JenkinsX 提供商業支持，包括：",-1)),e[34]||(e[34]=t("ul",null,[t("li",null,"訪問 CloudBees 的專業技術技能"),t("li",null,"24x7 技術支持"),t("li",null,"訪問 CloudBees 的文檔和在線知識庫")],-1)),e[35]||(e[35]=t("h4",{id:"kubernetes",tabindex:"-1"},[s("Kubernetes "),t("a",{class:"header-anchor",href:"#kubernetes","aria-label":"Permalink to “Kubernetes”"},"​")],-1)),t("p",null,[e[7]||(e[7]=s("隨着越來越多的組織尋求企業級的容器編排解決方案，",-1)),l(p,{href:"https://opensource.com/resources/what-is-kubernetes"},{default:r(()=>[...e[6]||(e[6]=[s("Kubernetes",-1)])]),_:1}),e[8]||(e[8]=s(" 的發展成為必然。儘管有人批評其複雜性。",-1))]),t("p",null,[e[10]||(e[10]=s("自然而然的，Kubernetes 周邊有完整的、蓬勃發展的產業。根據 Allied 市場調研的數據，全球容器和 ",-1)),l(p,{href:"https://enterprisersproject.com/article/2019/1/kubernetes-security-4-tips-manage-risks?intcmp=7013a000002qLH8AAM"},{default:r(()=>[...e[9]||(e[9]=[s("Kubernetes 安全",-1)])]),_:1}),e[11]||(e[11]=s(" 市場在 2020 年的估值為 7.14 億美元，預計到 2030 年將達到 8.42 億美元。",-1))]),e[36]||(e[36]=a('<h3 id="目前的-devops-工具鏈" tabindex="-1">目前的 DevOps 工具鏈 <a class="header-anchor" href="#目前的-devops-工具鏈" aria-label="Permalink to “目前的 DevOps 工具鏈”">​</a></h3><p>各個行業仍有很多<ruby>自建<rt>build-your-own</rt></ruby>（BYO）的 CI/CD 工具鏈在發揮作用。支持 DevOps 功能的開源項目仍在蓬勃發展。</p><p>BYO 工具鏈可以集成其他工具，而且非常具有擴展性，這對於持續迭代其 DevOps 實踐的組織來説一直是一個優勢。在出於業務、IT 和安全原因尋求標準化的企業中，缺乏標準的材料清單可能是個麻煩。</p><p>雖然 DevOps 平台的出現並沒有被忽視，但許多組織早在大流行之前就將他們的 CI/CD 工具鏈遷移到了公有云。長期以來，工具鏈本身的安全性一直是一個不斷上升的問題，而公有云基礎設施提供了身份訪問管理（IAM）和其他安全功能來控制訪問。</p><h3 id="devops-平台是敵是友" tabindex="-1">DevOps 平台是敵是友？ <a class="header-anchor" href="#devops-平台是敵是友" aria-label="Permalink to “DevOps 平台是敵是友？”">​</a></h3><p>DevOps 平台是一個端到端的解決方案，它將 CI/CD 工具鏈的所有功能放入雲中。DevOps 平台的例子包括 GitLab 和 Harness。GitHub 也在採取行動，使自己成為一個 DevOps 平台。</p><h4 id="優勢-即便只從企業買家角度考慮" tabindex="-1">優勢（即便只從企業買家角度考慮） <a class="header-anchor" href="#優勢-即便只從企業買家角度考慮" aria-label="Permalink to “優勢（即便只從企業買家角度考慮）”">​</a></h4><p>DevOps 平台對那些已經適應了 SaaS 和雲計算行業的基於消費和訂閲的定價的企業買家很有吸引力。在這個遠程和混合工作的世界裏，對可維護性、安全、合規性和開發人員的生產力的擔憂肯定是技術領導者的首要考慮。對這些人來説，在 DevOps 平台上實現標準化是很有吸引力的。</p><h4 id="劣勢" tabindex="-1">劣勢 <a class="header-anchor" href="#劣勢" aria-label="Permalink to “劣勢”">​</a></h4><p>在依賴供應商提供的 DevOps 工具鏈時，人們會想到對供應商鎖定功能的古老擔憂。開發團隊構建和維護其工具鏈的可擴展性不會像他們從頭開始製作工具鏈時那樣，更不用説引入新的工具來改善他們的工作流程了。</p><p>DevOps 平台供應商也有潛在的經濟方面的劣勢。想一想，一個被高估的 DevOps 工具初創公司如果沒有達到其投資者的高額財務目標，可能會發生什麼。同樣，也可能有一些較小的初創供應商得不到下一輪的資金，而慢慢消失。</p><p>雖然 DevOps 平台的出現在很多方面都是有意義的，但它確實違背了促成我們今天使用的 DevOps 工具的開源精神。</p><h3 id="devops-工具-一個拐點" tabindex="-1">DevOps 工具：一個拐點 <a class="header-anchor" href="#devops-工具-一個拐點" aria-label="Permalink to “DevOps 工具：一個拐點”">​</a></h3><p>隨着工作模式的改變，人們對 DevOps 工具鏈的安全和合規性的關注必然會增加。</p><h4 id="正在變化的工作環境" tabindex="-1">正在變化的工作環境 <a class="header-anchor" href="#正在變化的工作環境" aria-label="Permalink to “正在變化的工作環境”">​</a></h4><p>我們的工作方式與企業其他部門一樣影響着 DevOps 團隊。遠程和混合 DevOps 團隊需要安全的工具鏈。整個流水線中不斷變化的協作和報告要求，如異步工作和經理要求返回辦公室等，也是日益增長的必要條件。</p><h4 id="軟件供應鏈安全市場" tabindex="-1">軟件供應鏈安全市場 <a class="header-anchor" href="#軟件供應鏈安全市場" aria-label="Permalink to “軟件供應鏈安全市場”">​</a></h4><p>在高調的攻擊和美國聯邦政府的回應之後，軟件供應鏈安全市場引起了很多關注。目前還沒有組織將軟件供應鏈的攻擊歸咎於開源，但我們將看到 DevOps/DevSecOps 實踐和工具的延伸，以對抗這種威脅。不過，當一切都結束時，DevOps/DevSecOps 的工具和實踐將超過一些轉向這一趨勢的初創公司。</p><h3 id="結語" tabindex="-1">結語 <a class="header-anchor" href="#結語" aria-label="Permalink to “結語”">​</a></h3><p>對於 DevOps 領域的開源軟件（OSS）項目來説，這還遠遠沒有結束，但 DevOps 利益相關者有權開始詢問未來的工具鏈。然而，OSS DevOps 項目確實需要考慮它們的未來，特別是考慮到日益增長的直接影響流水線的安全和合規性問題。</p>',20)),t("p",null,[e[13]||(e[13]=s("DevOps 平台供應商與開源工具的未來趨勢是合作性競爭，即 DevOps 平台供應商向作為其平台基礎的開源工具貢獻時間、金錢和資源。一個有趣的例子就是 ",-1)),l(p,{href:"https://www.opsverse.io/"},{default:r(()=>[...e[12]||(e[12]=[s("OpsVerse",-1)])]),_:1}),e[14]||(e[14]=s("，它用他們為客户管理的開源工具提供了一個 DevOps 平台。",-1))]),e[37]||(e[37]=t("p",null,"然後，還有一個未來，隨着更多的企業構建的工具鏈遷移到雲端，開源 DevOps 工具項目將繼續繁榮和創新。",-1)),e[38]||(e[38]=t("hr",null,null,-1)),t("p",null,[e[16]||(e[16]=s("via: ",-1)),l(p,{href:"https://opensource.com/article/22/10/open-source-devops-tools"},{default:r(()=>[...e[15]||(e[15]=[s("https://opensource.com/article/22/10/open-source-devops-tools",-1)])]),_:1})]),t("p",null,[e[21]||(e[21]=s("作者：",-1)),l(p,{href:"https://opensource.com/users/willkelly"},{default:r(()=>[...e[17]||(e[17]=[s("Will Kelly",-1)])]),_:1}),e[22]||(e[22]=s(" 選題：",-1)),l(p,{href:"https://github.com/lkxed"},{default:r(()=>[...e[18]||(e[18]=[s("lkxed",-1)])]),_:1}),e[23]||(e[23]=s(" 譯者：",-1)),l(p,{href:"https://github.com/lxbwolf"},{default:r(()=>[...e[19]||(e[19]=[s("lxbwolf",-1)])]),_:1}),e[24]||(e[24]=s(" 校對：",-1)),l(p,{href:"https://github.com/wxy"},{default:r(()=>[...e[20]||(e[20]=[s("wxy",-1)])]),_:1})]),t("p",null,[e[27]||(e[27]=s("本文由 ",-1)),l(p,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...e[25]||(e[25]=[s("LCTT",-1)])]),_:1}),e[28]||(e[28]=s(" 原創編譯，",-1)),l(p,{href:"https://linux.cn/"},{default:r(()=>[...e[26]||(e[26]=[s("Linux中國",-1)])]),_:1}),e[29]||(e[29]=s(" 榮譽推出",-1))])])}const C=o(u,[["render",v]]);export{h as __pageData,C as default};
